/* ================= DRONE DE LIAISON — sprite unique =================
   Un seul sprite de profil (asset du propriétaire), retourné en miroir selon
   le sens du déplacement ÉCRAN. PATROUILLE : le drone décolle de la soute
   (au pied de la balise), rejoint UNE COURBE FERMÉE ET LISSE qui contourne
   les quatre côtés du plateau (rectangle arrondi paramétrique — fini les
   segments à coins, retour 16/08), fait un tour complet, revient et RENTRE
   en soute par fondu (il ne se gare plus une case sous la balise). En vol il
   est dessiné DEVANT tout le décor (il volait derrière la montagne et
   disparaissait). Rien en sauvegarde. */
const DR1 = { ok: false, img: null, hw: 0.420, mips: {} };
(function () {
  const img = new Image();
  img.onload = () => { DR1.img = img; DR1.ok = true; };
  img.src = "data:image/webp;base64,";
})();
function dr1Img(px2) {
  const k = [110, 200, 300].find((v) => v >= px2) || 300;
  let c = DR1.mips[k];
  if (!c) {
    c = DR1.mips[k] = document.createElement("canvas");
    c.width = k; c.height = Math.round(k * DR1.hw);
    c.getContext("2d").drawImage(DR1.img, 0, 0, c.width, c.height);
  }
  return c;
}
const DRONES = [];
for (let i = 0; i < 2; i++) DRONES.push({
  on: false, phase: "IDLE", tp: 0, seed: i * 977 + 131,
  wx: 0, wy: 0, alt: 0, v: 0, p: 0, len: 1, flip: false, fade: 0,
  ax: 0, ay: 0, bx: 0, by: 0, c1x: 0, c1y: 0, c2x: 0, c2y: 0,
  th: 0, thLeft: 0,
});
// point d'attache : SUR la plateforme de la balise, juste devant le faisceau
// (retour 17/08 : à +0,55 il se posait sur le bâtiment voisin). Le drone s'y
// GARE entre deux patrouilles (DR_PAUSE) — visible, posé, comme au hangar.
function drHome() { return [SRC.x + 0.05, SRC.y + 0.05]; }
/* LA BOUCLE DE PATROUILLE : courbe fermée et lisse qui longe les quatre côtés
   du plateau — rectangle arrondi paramétrique (squircle). L'exposant k règle
   l'arrondi des coins (plus petit = plus carré, colle mieux aux côtés). */
function drLoopPos(th, out) {
  const lo = bmin() + 0.9, hi = bmax() - 0.9;
  const c = (lo + hi) / 2, R = (hi - lo) / 2, k = 0.42;
  const f = (u) => Math.sign(u) * Math.pow(Math.abs(u), k);
  out.x = c + R * f(Math.cos(th));
  out.y = c + R * f(Math.sin(th));
  return out;
}
const _lp = { x: 0, y: 0 }, _lp2 = { x: 0, y: 0 };
function drLaunch(dr, ax, ay, bx, by) {
  dr.ax = ax; dr.ay = ay; dr.bx = bx; dr.by = by;
  const dx = bx - ax, dy = by - ay;
  const L = Math.hypot(dx, dy) || 0.01;
  // courbe arrondie : le segment bombe légèrement vers l'intérieur du plateau
  const cx = (bmin() + bmax()) / 2, cy = cx;
  const mx = ax + dx / 2, my = ay + dy / 2;
  const vx = cx - mx, vy = cy - my;
  const vn = Math.hypot(vx, vy) || 1;
  const bombe = 0.55;
  dr.c1x = ax + dx * 0.3 + vx / vn * bombe; dr.c1y = ay + dy * 0.3 + vy / vn * bombe;
  dr.c2x = ax + dx * 0.7 + vx / vn * bombe; dr.c2y = ay + dy * 0.7 + vy / vn * bombe;
  dr.len = L * 1.1; dr.p = 0;
  dr.wx = ax; dr.wy = ay;
}
const _bz = { x: 0, y: 0 };
function drBez(dr, p) {
  const q = 1 - p;
  _bz.x = q * q * q * dr.ax + 3 * q * q * p * dr.c1x + 3 * q * p * p * dr.c2x + p * p * p * dr.bx;
  _bz.y = q * q * q * dr.ay + 3 * q * q * p * dr.c1y + 3 * q * p * p * dr.c2y + p * p * p * dr.by;
  return _bz;
}
/* VITESSE STABLE (retour 17/08) : la vitesse est asservie en PIXELS ÉCRAN
   (métrique isométrique, à z=1), pas en unités monde — sinon les tronçons
   « horizontaux » de l'iso paraissent 2× plus rapides (TW=92 vs TH=46) et le
   drone semble accélérer à chaque côté. Une seule rampe douce au départ, un
   seul freinage à l'approche finale : constant partout ailleurs. */
const DR_VPX = 88, DR_ALT = 18;                    // vitesse écran (px/s à z=1)
const DR_PAUSE = 90;                               // pause au sol entre deux patrouilles (s)
function drIsoLen(dx, dy) {
  return Math.hypot((dx - dy) * TW / 2, (dx + dy) * TH / 2);
}
function tickDrones(dt, t) {
  if (!DR1.ok) return;
  drTraffic(dt);
  for (const dr of DRONES) {
    if (!dr.on) continue;
    dr.tp += dt;
    const pwx = dr.wx, pwy = dr.wy;
    // cible de vitesse : constante, freinée seulement en toute fin de retour
    let cible = DR_VPX;
    if (dr.phase === "RETURN" && dr.p > 0.70) cible = DR_VPX * Math.max(0.22, (1 - dr.p) / 0.30);
    if (dr.phase === "LANDING" || dr.phase === "PARKED") cible = 0;
    dr.v += (cible - dr.v) * Math.min(1, dt * 2.2); // lissage unique (accel bornée)
    if (dr.phase === "TAKEOFF") {
      dr.alt = Math.min(1, dr.tp / 0.9);
      dr.fade = Math.max(dr.fade, Math.min(1, dr.tp / 0.45)); // fondu au 1er envol seulement
      if (dr.tp >= 0.9) { dr.phase = "JOIN"; dr.tp = 0; }
    } else if (dr.phase === "JOIN" || dr.phase === "RETURN") {
      const fin = dr.phase === "RETURN";
      /* avancement à vitesse ÉCRAN constante par BISSECTION : on n'avance un
         pas que si sa distance réelle tient dans le budget de pixels restant,
         sinon on divise le pas par deux. Dépassement impossible par
         construction — c'est ce qui tue les à-coups (retour 17/08 : la
         vitesse paramétrique des courbes varie trop pour un pas unique). */
      let budget = dr.v * dt, guard = 0;
      while (budget > 0.05 && dr.p < 1 && guard++ < 400) {
        let dp = Math.min(0.03, 1 - dr.p);
        const a0 = drBez(dr, dr.p); const a0x = a0.x, a0y = a0.y;
        let d = 0;
        for (let k = 0; k < 14; k++) {
          const a1 = drBez(dr, dr.p + dp);
          d = drIsoLen(a1.x - a0x, a1.y - a0y);
          if (d <= budget) break;
          dp /= 2;
        }
        if (d > budget) break;
        dr.p += dp; budget -= Math.max(d, 0.02);
      }
      const a = drBez(dr, dr.p);
      dr.wx = a.x; dr.wy = a.y;
      if (dr.p >= 1) {
        if (!fin) { dr.phase = "LOOP"; dr.thLeft = Math.PI * 2; }  // un tour complet
        else { dr.phase = "LANDING"; dr.tp = 0; }
      }
    } else if (dr.phase === "LOOP") {
      // même principe le long du squircle : la dérivée du profil |u|^k explose
      // aux coins — seule la bissection garantit une vitesse écran constante
      let budget = dr.v * dt, guard = 0;
      while (budget > 0.05 && dr.thLeft > 0 && guard++ < 400) {
        let dth = Math.min(0.02, dr.thLeft);
        drLoopPos(dr.th, _lp);
        let d = 0;
        for (let k = 0; k < 14; k++) {
          drLoopPos(dr.th + dth, _lp2);
          d = drIsoLen(_lp2.x - _lp.x, _lp2.y - _lp.y);
          if (d <= budget) break;
          dth /= 2;
        }
        if (d > budget) break;
        dr.th += dth; dr.thLeft -= dth; budget -= Math.max(d, 0.02);
      }
      drLoopPos(dr.th, _lp);
      dr.wx = _lp.x; dr.wy = _lp.y;
      if (dr.thLeft <= 0) {                         // tour bouclé : on rentre
        const h = drHome();
        drLaunch(dr, dr.wx, dr.wy, h[0], h[1]);
        dr.phase = "RETURN";
      }
    } else if (dr.phase === "LANDING") {
      dr.alt = Math.max(0, 1 - dr.tp / 0.9);        // se POSE sur la balise (visible)
      if (dr.tp >= 0.9) { dr.phase = "PARKED"; dr.tp = 0; }
    } else if (dr.phase === "PARKED") {
      // garé sur la plateforme : il ne repart qu'au bout de DR_PAUSE (retour 17/08)
      if (dr.tp >= DR_PAUSE) {
        dr.tp = 0; dr.phase = "TAKEOFF";
        const h = drHome();
        dr.wx = h[0]; dr.wy = h[1];
        dr.th = 0; drLoopPos(dr.th, _lp);
        drLaunch(dr, h[0], h[1], _lp.x, _lp.y);
      }
    }
    // une face par sens de déplacement ÉCRAN (hystérésis anti-battement)
    const ddx = (dr.wx - pwx) - (dr.wy - pwy);
    if (Math.abs(ddx) > 1e-4) dr.flip = ddx > 0;
  }
}
let drAcc = 0, drCool = 0;
function drTraffic(dt) {
  drAcc += dt;
  if (drAcc < 1) return;
  drAcc = 0; drCool = Math.max(0, drCool - 1);
  if (view !== "col" || drCool > 0) return;
  if (DRONES.some((d) => d.on)) return;      // UN SEUL drone en circulation
  if (enUse() > enCap()) return;             // panne d'énergie : pas de patrouille
  drSpawn();
  drCool = 10 + ((mulberry32((performance.now() | 0) ^ 0xD10)() * 12) | 0);
}
function drSpawn() {
  const dr = DRONES.find((d) => !d.on);
  if (!dr) return null;
  const h = drHome();
  dr.on = true; dr.phase = "TAKEOFF"; dr.tp = 0; dr.alt = 0; dr.fade = 0; dr.v = 0;
  dr.wx = h[0]; dr.wy = h[1];
  dr.th = 0;                                     // entrée de boucle : plein est
  drLoopPos(dr.th, _lp);
  drLaunch(dr, h[0], h[1], _lp.x, _lp.y);
  return dr;
}
function drawDrone16(dr, t) { // (nom conservé : appelé par la passe triée)
  const z = cam.z, p = w2s(dr.wx, dr.wy);
  if (p.x < -90 || p.x > W + 90 || p.y < -120 || p.y > H + 90) return;
  if (dr.fade <= 0) return;
  ctx.save();
  ctx.globalAlpha = dr.fade;                      // fondu soute (départ/retour)
  const bob = Math.sin(t / 460 + dr.seed) * 2.2 * z * Math.min(1, dr.alt * 2);
  const alt = dr.alt * DR_ALT * z;
  // l'ombre reste au sol, plus petite et plus claire en altitude
  const so = 0.30 - 0.16 * dr.alt, sr = (3.8 - 1.4 * dr.alt) * z;
  ctx.beginPath();
  ctx.ellipse(p.x, p.y, sr, sr * 0.5, 0, 0, Math.PI * 2);
  ctx.fillStyle = "rgba(20,10,4," + so.toFixed(2) + ")";
  ctx.fill();
  const sw = 0.16 * TW * z, sh = sw * DR1.hw;
  const py2 = p.y - alt + bob;
  ctx.save();
  if (dr.flip) { ctx.translate(p.x, py2); ctx.scale(-1, 1); ctx.translate(-p.x, -py2); }
  const gl = 0.14 + 0.07 * Math.sin(t / 220 + dr.seed) + 0.10 * (dr.v / DR_VPX);
  const g = ctx.createRadialGradient(p.x, py2 + sh * 0.34, 1, p.x, py2 + sh * 0.34, sw * 0.30);
  g.addColorStop(0, "rgba(90,190,255," + gl.toFixed(2) + ")");
  g.addColorStop(1, "rgba(90,190,255,0)");
  ctx.fillStyle = g;
  ctx.fillRect(p.x - sw * 0.35, py2, sw * 0.7, sh * 0.6);
  ctx.drawImage(dr1Img(sw * DPR), p.x - sw / 2, py2 - sh * 0.52, sw, sh);
  ctx.restore();
  ctx.restore();   // referme le save() du fondu
}

const GUIDE_BUILD = { 1: "coffret", 4: "extracteur", 7: "entrepot", 8: "centrale", 11: "switchhub", 14: "serveur", 16: "datacenter", 20: "reseau", 22: "console", 23: "forge" };
function nearestTile(pred) {
  let best = null, bd = 1e9;
  for (let y = bmin(); y <= bmax(); y++) for (let x = bmin(); x <= bmax(); x++) {
    if (!pred(x, y)) continue;
    const d = Math.abs(x - SRC.x) + Math.abs(y - SRC.y);
    if (d < bd) { bd = d; best = { x, y }; }
  }
  return best;
}
function guideWorldTarget() {
  if (view !== "col") return null;
  if (place) return { x: place.hx, y: place.hy, kind: "ghost" };
  const mi = S.mi;
  if (mi === 2) { const o = orbs[0]; return o && { x: o.x, y: o.y, kind: "orb" }; }
  if (mi === 0) return Object.assign({ kind: "crys" }, nearestTile((x, y) =>
    tileAt(x, y).kind === "crystal" && !S.units.some((u) => u.x === x && u.y === y)) || {});
  if (GUIDE_BUILD[mi]) { const t = nearestTile((x, y) => buildable(x, y) && posable(GUIDE_BUILD[mi], x, y)); return t && { x: t.x, y: t.y, kind: "tile" }; }
  if (mi === 5) { const b = S.buildings.find((b) => b.t === "extracteur"); return b && { x: b.x, y: b.y, kind: "bld", b }; }
  if (mi === 6) { const o = orbs[0]; return o && { x: o.x, y: o.y, kind: "orb" }; }
  if (mi === 9) { const b = S.buildings.find((b) => b.t === "centrale"); return b && { x: b.x, y: b.y, kind: "bld", b }; }
  if (mi === 10 || mi === 12) { const b = S.buildings.find((b2) => !netConnected(keyOf(b2))); return b && { x: b.x, y: b.y, kind: "bld", b }; }
  if (mi === 15) { const b = S.buildings.find((b) => b.t === "serveur"); return b && { x: b.x, y: b.y, kind: "bld", b }; }
  if (mi === 21) { const b = S.buildings.find((b) => BT[b.t].game); return b && { x: b.x, y: b.y, kind: "bld", b }; }
  if (mi === 24) { const b = S.buildings.find((b) => b.t === "forge"); return b && { x: b.x, y: b.y, kind: "bld", b }; }
  if (mi === 25) {
    if (!S.units.some((u) => u.t === "chasseur")) {
      const b = S.buildings.find((b) => b.t === "forge");
      return b && { x: b.x, y: b.y, kind: "bld", b };
    }
    const m = mobs[0];
    return m && { x: m.x, y: m.y, kind: "mob" };
  }
  if (mi === 26) return { x: SRC.x, y: SRC.y, kind: "src" };
  return null;
}
function drawCrevasseHint(t) {
  if (view !== "col" || S.mi < 6 || S.cleared.length > 0) return;
  const c = nearestTile((x, y) => tileAt(x, y).kind === "crevasse");
  if (!c) return;
  const p = w2s(c.x, c.y), z = cam.z;
  const pulse = 0.5 + 0.5 * Math.sin(t / 300);
  // pas d'anneau autour de la crevasse : le « ? » suffit (retour propriétaire)
  ctx.font = Math.round(15 * z) + "px " + UI_FONT;
  ctx.textAlign = "center";
  ctx.fillStyle = "#ff9a4d";
  ctx.shadowColor = "#ff9a4d"; ctx.shadowBlur = 10;
  ctx.fillText("?", p.x, p.y - 18 * z - pulse * 5 * z);
  ctx.shadowBlur = 0;
}
function drawPlaceHalo(t) {
  if (!place || view !== "col") return;
  const z = cam.z, p = w2s(place.hx, place.hy);
  const s = place.kind === "unit" ? FP_UNIT : fpOf(place.t, place.hx, place.hy);
  const col = place.valid ? "#3cdc82" : "#ff6b6b";
  ctx.save();
  diamond(ctx, p.x, p.y, s * TW * z, s * TH * z);
  ctx.fillStyle = place.valid ? "rgba(60,220,130,.18)" : "rgba(255,107,107,.18)";
  ctx.fill();
  /* Le SIGNAL D'AIMANTATION : trait plein quand le fantôme est collé au centre
     d'une case, pointillé quand il flotte en pose libre. C'est le seul retour
     visuel du seuil d'aimant — sans lui, on ne saurait pas si la pose va
     s'aligner ou rester où on l'a mise. */
  if (place.snap) { ctx.strokeStyle = col; ctx.lineWidth = 2.5; ctx.stroke(); }
  else { ctx.setLineDash([6, 4]); ctx.strokeStyle = col; ctx.lineWidth = 2; ctx.stroke(); ctx.setLineDash([]); }
  // le « petit bord » demandé : la zone de marge, en pointillé fin
  diamond(ctx, p.x, p.y, (s + FP_MARGE) * TW * z, (s + FP_MARGE) * TH * z);
  ctx.setLineDash([3, 4]); ctx.lineWidth = 1.2;
  ctx.globalAlpha = 0.4; ctx.strokeStyle = col; ctx.stroke();
  ctx.setLineDash([]); ctx.globalAlpha = 1;
  // aimanté : la croix du centre de case, discrète
  if (place.snap) {
    ctx.globalAlpha = 0.55; ctx.strokeStyle = col; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(p.x - 6, p.y); ctx.lineTo(p.x + 6, p.y); ctx.moveTo(p.x, p.y - 4); ctx.lineTo(p.x, p.y + 4); ctx.stroke();
    ctx.globalAlpha = 1;
  }
  // ce qui bloque, entouré de rouge pulsant
  if (!place.valid && place.bx != null) {
    const q = w2s(place.bx, place.by);
    const pu = 0.5 + 0.5 * Math.sin(t / 450);
    diamond(ctx, q.x, q.y, TW * 0.9 * z, TH * 0.9 * z);
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = "rgba(255,107,107," + (0.4 + 0.5 * pu).toFixed(2) + ")";
    ctx.lineWidth = 2; ctx.stroke(); ctx.setLineDash([]);
  }
  ctx.restore();
}
function drawPlaceGhost(t) {
  if (!place) return;
  const z = cam.z, p = w2s(place.hx, place.hy);
  ctx.save();
  ctx.globalAlpha = place.valid ? 0.62 : 0.3;
  if (place.kind === "unit") {
    if (DRN.ok) {
      const vw = DRONE_W * TW * z, vh = vw * DRN.hw;
      ctx.drawImage(drnImg(), p.x - vw / 2, p.y - 26 * z - vh / 2, vw, vh);
    }
  } else {
    // le fantôme montre la tuile du niveau qui sera POSÉ : un ouvrage neuf est
    // au niveau 1 (en miroir il sort des soutes au niveau du Chantier)
    const nv = place.kind === "move" && place.mv ? place.mv.l : (MIRROR ? (mirrorStock(place.t) || 1) : 1);
    const tk = tsprKey(place.t, nv);
    const ts = TSPR[tk];
    if (ts && ts.ok) {
      const img = tsprImg(tk);
      const sw = ts.w * TW * z, sh = sw * ts.hw;
      plateauClipPath(); ctx.clip();
      ctx.drawImage(img, p.x - ts.ax * sw, p.y + TH * ts.oy * z - ts.ay * sh, sw, sh);
    } else {
      const def = BT[place.t];
      diamond(ctx, p.x, p.y, TW * 0.8 * z, TH * 0.8 * z);
      ctx.fillStyle = "#22262e"; ctx.fill();
      isoBox(p.x, p.y, TW * 0.62 * z, TH * 0.62 * z, 21 * z, def.col);
    }
  }
  ctx.restore();
}
function drawGuide(t) {
  const gt = guideWorldTarget();
  if (!gt || gt.x == null) return;
  const p = w2s(gt.x, gt.y), z = cam.z;
  const pulse = 0.5 + 0.5 * Math.sin(t / 220);
  if (gt.kind === "ghost") return; // le halo de pose est la seule indication
  if (gt.kind === "tile" || gt.kind === "src" || gt.kind === "crys") {
    diamond(ctx, p.x, p.y, TW * z * (1 + 0.06 * pulse), TH * z * (1 + 0.06 * pulse));
    ctx.strokeStyle = "rgba(255,200,87," + (0.45 + 0.5 * pulse).toFixed(2) + ")";
    ctx.lineWidth = 2.5;
    ctx.shadowColor = "#ffc857"; ctx.shadowBlur = 10;
    ctx.stroke(); ctx.shadowBlur = 0;
  }
  const hover = gt.kind === "bld" ? 62 : gt.kind === "orb" ? 58 : gt.kind === "mob" ? 34 : gt.kind === "src" ? 138 : gt.kind === "crys" ? 38 : 26;
  ctx.font = Math.round(17 * z) + "px " + UI_FONT;
  ctx.textAlign = "center";
  ctx.fillStyle = "#ffc857";
  ctx.shadowColor = "#ffc857"; ctx.shadowBlur = 12;
  ctx.fillText("▼", p.x, p.y - hover * z - pulse * 7 * z);
  ctx.shadowBlur = 0;
}

